// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. update_time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GormEventReportRepository) Delete(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	res := r.markDeleted(ctx, r.DB, key)
	if res.Error != nil {
		return repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		return repox.ErrNotFound
	}
	return nil
}

// markDeleted sets the soft-delete mark on the live row found by key
// (rowKey) through db: Delete's write, which a Batch runs inside its
// transaction.
func (r *GormEventReportRepository) markDeleted(ctx context.Context, db *gorm.DB, key string) *gorm.DB {
	now := time.Now()
	return db.WithContext(ctx).Model(&eventreport.EventReport{}).
		Where("id = ? AND delete_time IS NULL", key).
		Updates(map[string]any{"delete_time": now, "update_time": now, "etag": repox.NewULID(), "expire_time": repox.ExpireAt(now, r.Retention)})
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GormEventReportRepository) Undelete(ctx context.Context, name string) (*event_reportv1.EventReport, error) {
	key, err := r.rowKey(name)
	if err != nil {
		return nil, err
	}
	res := r.DB.WithContext(ctx).Model(&eventreport.EventReport{}).
		Where("id = ? AND delete_time IS NOT NULL", key).
		Updates(map[string]any{"delete_time": nil, "etag": repox.NewULID(), "expire_time": nil})
	if res.Error != nil {
		return nil, repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		if _, err := r.get(ctx, key); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, key)
}

// Purge removes the record addressed by its resource name for good.
